export const LANGS = [
  ['en', 'English'],
  ['de', 'Deutsch'],
  ['fr', 'Français'],
  ['es', 'Español'],
  ['ja', '日本語'],
  ['ar', 'العربية'], // Modern Standard Arabic (24 Oct 2026): the words run right to left; the layout stays as it is
];

export function deviceLang() {
  try {
    const loc = (Intl.DateTimeFormat().resolvedOptions().locale || 'en').slice(0, 2).toLowerCase();
    return LANGS.some(([k]) => k === loc) ? loc : 'en';
  } catch (e) { return 'en'; }
}

