  'Sleep timer': { de: 'Einschlaf-Timer', fr: 'Minuteur de sommeil', es: 'Temporizador para dormir', ja: 'おやすみタイマー', ar: "مؤقت النوم" },
  '{n} min': { de: '{n} Min.', fr: '{n} min', es: '{n} min', ja: '{n}ぷん', ar: "{n} د" },
  'Audio Player on screen': { de: 'Audio-Player anzeigen', fr: 'Lecteur audio à l’écran', es: 'Reproductor de audio en pantalla', ja: 'オーディオプレーヤーを ひょうじ', ar: "مشغّل الصوت على الشاشة" },
  'Show': { de: 'Zeigen', fr: 'Afficher', es: 'Mostrar', ja: 'みせる', ar: "إظهار" },
  'Hide': { de: 'Verbergen', fr: 'Masquer', es: 'Ocultar', ja: 'かくす', ar: "إخفاء" },
  'Audio Player': { de: 'Audio-Player', fr: 'Lecteur audio', es: 'Reproductor de audio', ja: 'オーディオプレーヤー', ar: "مشغّل الصوت" },
  'Who is reading? Tap your name.': { de: 'Wer liest? Tippe auf deinen Namen.', fr: 'Qui lit ? Touche ton prénom.', es: '¿Quién lee? Toca tu nombre.', ja: 'だれがよむ？ じぶんのなまえをタップしてね。', ar: "من يقرأ؟ المس اسمك." },
  'Tap a child to change their name, colour or age.': { de: 'Tippe auf ein Kind, um Name, Farbe oder Alter zu ändern.', fr: 'Touche un enfant pour changer son prénom, sa couleur ou son âge.', es: 'Toca a un niño para cambiar su nombre, color o edad.', ja: 'こどもをタップして、なまえ・いろ・ねんれいをかえます。', ar: "المس اسم طفل لتغيير اسمه أو لونه أو عمره." },
  'Give each child their own notebook, badges, playlists and settings. Their age decides which books they see.': { de: 'Gib jedem Kind sein eigenes Notizbuch, eigene Abzeichen, Playlists und Einstellungen. Sein Alter bestimmt, welche Bücher es sieht.', fr: 'Donnez à chaque enfant son carnet, ses badges, ses listes de lecture et ses réglages. Son âge décide des livres qu’il voit.', es: 'Da a cada niño su propio cuaderno, insignias, listas y ajustes. Su edad decide qué libros ve.', ja: 'こどもひとりひとりに、ノート・バッジ・プレイリスト・せっていを。ねんれいで、みえるほんがきまります。', ar: "امنح كل طفل دفتره وشاراته وقوائم تشغيله وإعداداته الخاصة. يحدد عمره الكتب التي يراها." },
  'Reading now': { de: 'Liest gerade', fr: 'Lit en ce moment', es: 'Leyendo ahora', ja: 'よんでいるひと', ar: "يقرأ الآن" },
  'Age {n}': { de: '{n} Jahre', fr: '{n} ans', es: '{n} años', ja: '{n}さい', ar: "العمر {n}" },
  'Add a child': { de: 'Kind hinzufügen', fr: 'Ajouter un enfant', es: 'Añadir un niño', ja: 'こどもをついか', ar: "إضافة طفل" },
  'Done editing': { de: 'Fertig bearbeitet', fr: 'Modifications terminées', es: 'Terminar de editar', ja: 'へんしゅう おわり', ar: "انتهى التعديل" },
  'Edit profiles': { de: 'Profile bearbeiten', fr: 'Modifier les profils', es: 'Editar perfiles', ja: 'プロフィールを へんしゅう', ar: "تعديل الملفات الشخصية" },
  'A grown-up has turned off switching profiles.': { de: 'Ein Erwachsener hat das Wechseln der Profile ausgeschaltet.', fr: 'Un adulte a désactivé le changement de profil.', es: 'Un adulto ha desactivado el cambio de perfil.', ja: 'おとなが、プロフィールのきりかえをオフにしています。', ar: "أوقف أحد الكبار التبديل بين الملفات الشخصية." },
  'Books, the membership, recordings, the language and the music are shared by the whole family.': { de: 'Bücher, Mitgliedschaft, Aufnahmen, Sprache und Musik teilt sich die ganze Familie.', fr: 'Les livres, l’abonnement, les enregistrements, la langue et la musique sont partagés par toute la famille.', es: 'Los libros, la membresía, las grabaciones, el idioma y la música son de toda la familia.', ja: 'ほん・メンバーシップ・ろくおん・ことば・おんがくは、かぞくみんなでつかいます。', ar: "الكتب والاشتراك والتسجيلات واللغة والموسيقى مشتركة بين العائلة كلها." },
  'Name': { de: 'Name', fr: 'Prénom', es: 'Nombre', ja: 'なまえ', ar: "الاسم" },
  'Colour': { de: 'Farbe', fr: 'Couleur', es: 'Color', ja: 'いろ', ar: "اللون" },
  'Age': { de: 'Alter', fr: 'Âge', es: 'Edad', ja: 'ねんれい', ar: "العمر" },
  'Books rated for older children are hidden.': { de: 'Bücher für ältere Kinder werden ausgeblendet.', fr: 'Les livres pour enfants plus âgés sont masqués.', es: 'Se ocultan los libros para niños mayores.', ja: 'もっとおおきいこむけのほんは、かくれます。', ar: "الكتب المخصصة للأطفال الأكبر سنًا مخفية." },
  'Save': { de: 'Speichern', fr: 'Enregistrer', es: 'Guardar', ja: 'ほぞん', ar: "حفظ" },
  'Remove {name}? Their notebook and badges stay on this phone, but nobody will see them.': { de: '{name} entfernen? Notizbuch und Abzeichen bleiben auf dem Telefon, aber niemand sieht sie mehr.', fr: 'Retirer {name} ? Son carnet et ses badges restent sur le téléphone, mais personne ne les verra.', es: '¿Quitar a {name}? Su cuaderno e insignias quedan en el teléfono, pero nadie los verá.', ja: '{name}をけしますか？ ノートとバッジはでんわにのこりますが、だれにもみえなくなります。', ar: "هل تريد إزالة {name}؟ سيبقى الدفتر والشارات على هذا الهاتف، لكن لن يراها أحد." },
  'Remove': { de: 'Entfernen', fr: 'Retirer', es: 'Quitar', ja: 'けす', ar: "إزالة" },
