  'New playlist': { de: 'Neue Playlist', fr: 'Nouvelle liste', es: 'Nueva lista', ja: 'あたらしいプレイリスト', ar: "قائمة تشغيل جديدة" },
  'My playlist': { de: 'Meine Playlist', fr: 'Ma liste', es: 'Mi lista', ja: 'わたしのプレイリスト', ar: "قائمة تشغيلي" },
  'Playlist name': { de: 'Name der Playlist', fr: 'Nom de la liste', es: 'Nombre de la lista', ja: 'プレイリストのなまえ', ar: "اسم قائمة التشغيل" },
  'Tap books to add them. Tap again to take them out.': { de: 'Tippe auf Bücher, um sie hinzuzufügen. Nochmal tippen nimmt sie heraus.', fr: 'Touche des livres pour les ajouter. Touche encore pour les retirer.', es: 'Toca libros para añadirlos. Tócalos otra vez para quitarlos.', ja: 'ほんをタップしてついか。もういちどタップでとりだします。', ar: "المس الكتب لإضافتها. المسها مرة أخرى لإخراجها." },
