  'Tap any word to hear it.': { de: 'Tippe auf ein Wort, um es zu hören.', fr: 'Touche un mot pour l’entendre.', es: 'Toca una palabra para oírla.', ja: 'ことばを タップすると きこえます。', ar: "المس أي كلمة لتسمعها." },
  'Reading on your own. Turn the page when you’re ready.': { de: 'Du liest selbst. Blättere um, wenn du so weit bist.', fr: 'Tu lis tout seul. Tourne la page quand tu es prêt.', es: 'Lees tú solo. Pasa la página cuando quieras.', ja: 'じぶんで よもう。じゅんびが できたら ページを めくってね。', ar: "أنت تقرأ بنفسك. اقلب الصفحة عندما تكون جاهزًا." },
  '{name} will read the stories.': { de: '{name} liest die Geschichten vor.', fr: '{name} lira les histoires.', es: '{name} leerá los cuentos.', ja: '{name}が おはなしを よみます。', ar: "سيقرأ {name} القصص." },
  '{mode} is on.': { de: '{mode} ist an.', fr: '{mode} est activé.', es: '{mode} está activado.', ja: '{mode} に しました。', ar: "{mode} قيد التشغيل." },
