  'That drawing couldn’t be saved. Try again.': { de: 'Die Zeichnung konnte nicht gespeichert werden. Versuch es noch einmal.', fr: 'Le dessin n’a pas pu être enregistré. Réessayez.', es: 'No se pudo guardar el dibujo. Inténtalo de nuevo.', ja: 'えを ほぞん できませんでした。もういちど ためしてください。', ar: "تعذّر حفظ هذا الرسم. حاول مرة أخرى." },
  'Upload or record a sound': { de: 'Klang hochladen oder aufnehmen', fr: 'Importer ou enregistrer un son', es: 'Subir o grabar un sonido', ja: 'おとを アップロード／ろくおん', ar: "تحميل صوت أو تسجيله" },
  'Press and hold your own sound to remove it.': { de: 'Halte deinen eigenen Klang gedrückt, um ihn zu entfernen.', fr: 'Appuyez longuement sur votre son pour le retirer.', es: 'Mantén pulsado tu sonido para quitarlo.', ja: 'じぶんの おとを ながおしすると けせます。', ar: "اضغط مطولًا على صوتك لإزالته." },
  'Add a sound from your phone, or record one yourself: rain on your window, the sea, your cat purring.': { de: 'Füge einen Klang von deinem Telefon hinzu oder nimm selbst einen auf: Regen am Fenster, das Meer, deine schnurrende Katze.', fr: 'Ajoutez un son depuis votre téléphone, ou enregistrez-en un : la pluie sur la fenêtre, la mer, votre chat qui ronronne.', es: 'Añade un sonido desde tu teléfono o graba uno: la lluvia en la ventana, el mar, tu gato ronroneando.', ja: 'スマホの おとを ついかするか、じぶんで ろくおん しましょう。まどの あめ、うみ、ねこの ゴロゴロ など。', ar: "أضف صوتًا من هاتفك، أو سجّل واحدًا بنفسك: المطر على نافذتك، البحر، خرخرة قطتك." },
  'Our sound': { de: 'Unser Klang', fr: 'Notre son', es: 'Nuestro sonido', ja: 'わたしたちの おと', ar: "صوتنا" },
  'Add to Sounds': { de: 'Zu den Klängen hinzufügen', fr: 'Ajouter aux sons', es: 'Añadir a los sonidos', ja: 'おとに ついか', ar: "إضافة إلى الأصوات" },
