  'Alarm off': { de: 'Wecker aus', fr: 'Réveil désactivé', es: 'Alarma desactivada', ja: 'めざまし オフ', ar: "المنبّه متوقف" },
  'Settings and Profiles': { de: 'Einstellungen und Profile', fr: 'Réglages et profils', es: 'Ajustes y perfiles', ja: 'せっていと プロフィール', ar: "الإعدادات والملفات الشخصية" },
  'Language, parental controls and profiles': { de: 'Sprache, Kindersicherung und Profile', fr: 'Langue, contrôle parental et profils', es: 'Idioma, control parental y perfiles', ja: 'ことば、ほごしゃ せってい、プロフィール', ar: "اللغة والرقابة الأبوية والملفات الشخصية" },
  'Each child can have their own profile, with their own notebook, badges, playlists and settings.': { de: 'Jedes Kind kann ein eigenes Profil haben, mit eigenem Notizbuch, eigenen Abzeichen, Playlists und Einstellungen.', fr: 'Chaque enfant peut avoir son propre profil, avec son carnet, ses badges, ses listes de lecture et ses réglages.', es: 'Cada niño puede tener su propio perfil, con su cuaderno, sus insignias, sus listas y sus ajustes.', ja: 'こどもごとに プロフィールを つくれます。ノート、バッジ、プレイリスト、せっていも それぞれです。', ar: "يمكن لكل طفل أن يكون له ملفه الشخصي، مع دفتره وشاراته وقوائم تشغيله وإعداداته الخاصة." },
  'Manage profiles': { de: 'Profile verwalten', fr: 'Gérer les profils', es: 'Gestionar perfiles', ja: 'プロフィールを かんり', ar: "إدارة الملفات الشخصية" },
  'Open playlists': { de: 'Playlists öffnen', fr: 'Ouvrir les listes de lecture', es: 'Abrir listas', ja: 'プレイリストを ひらく', ar: "فتح قوائم التشغيل" },
  'Relaxing and gentle': { de: 'Entspannend und sanft', fr: 'Apaisant et doux', es: 'Relajante y suave', ja: 'ゆったり やさしく', ar: "هادئ ولطيف" },
  'Find and read your favorite books': { de: 'Finde und lies deine Lieblingsbücher', fr: 'Trouve et lis tes livres préférés', es: 'Encuentra y lee tus libros favoritos', ja: 'すきな本を さがしてよもう', ar: "ابحث عن كتبك المفضلة واقرأها" },
  'Language, parental and profiles': { de: 'Sprache, Eltern und Profile', fr: 'Langue, parents et profils', es: 'Idioma, padres y perfiles', ja: 'ことば、ほごしゃ、プロフィール', ar: "اللغة والرقابة الأبوية والملفات" },
  'Modes, voices, fonts and sounds': { de: 'Modi, Stimmen, Schriften und Klänge', fr: 'Modes, voix, polices et sons', es: 'Modos, voces, letras y sonidos', ja: 'モード、こえ、もじ、おと', ar: "الأوضاع والأصوات والخطوط والمؤثرات الصوتية" },
